mapper.select:
SELECT b.id, b.title, CASE WHEN LENGTH(b.content) > 200 THEN CONCAT(SUBSTRING(b.content, 1, 200), '...') ELSE b.content END AS summary, u.username AS authorName, b.created_at AS createdAt FROM blog b LEFT JOIN user u ON b.user_id = u.id
u.username = #{author}
ORDER BY b.created_at DESC LIMIT #{limit} OFFSET #{offset}
